css:
/* Sunset glow effects */
.sound-button {
  background: linear-gradient(45deg, var(--button-bg) 0%, var(--accent-primary) 100%);
  border: 2px solid var(--accent-secondary);
  border-radius: 15px;
  transition: all 0.4s ease;
  position: relative;
  overflow: hidden;
}

.sound-button::before {
  content: '';
  position: absolute;
  top: -50%;
  left: -50%;
  width: 200%;
  height: 200%;
  background: linear-gradient(45deg, transparent, rgba(255, 107, 107, 0.3), transparent);
  transform: rotate(45deg);
  transition: all 0.6s ease;
  opacity: 0;
}

.sound-button:hover::before {
  opacity: 1;
  animation: shimmer 1.5s ease-in-out infinite;
}

@keyframes shimmer {
  0% { transform: translateX(-100%) rotate(45deg); }
  100% { transform: translateX(100%) rotate(45deg); }
}

.sound-button:hover {
  transform: scale(1.08) rotate(2deg);
  box-shadow: 0 8px 25px rgba(255, 107, 107, 0.4);
}

/* Sunset gradient background */
#sound-grid {
  background: linear-gradient(135deg, var(--bg-primary) 0%, var(--bg-secondary) 25%, var(--accent-primary) 50%, var(--accent-secondary) 75%, var(--bg-primary) 100%);
  background-size: 40px 40px;
  border: 3px solid var(--accent-secondary);
  border-radius: 20px;
  box-shadow: 0 0 30px rgba(255, 107, 107, 0.3);
}
